/*
 * Tirtha Atlas service worker.
 *
 * Hand-rolled rather than generated by Workbox, for the same reason the rest of
 * this project has three dependencies: the whole file is 150 lines, every rule
 * in it is a decision someone should be able to read, and a generated one hides
 * exactly the decisions that matter here.
 *
 * WHY AN ATLAS OF TEMPLES NEEDS TO WORK OFFLINE
 * --------------------------------------------
 * The audience is standing at the site. Kedarnath is at 3,580 m up a bridle
 * path; Amarnath is a cave reached on foot; a great many of these 3,031 places
 * are villages where a data connection is a rumour. The moment the atlas is
 * most useful is exactly the moment the network is worst, so a page that has
 * already been read must stay readable, and the map must open at all.
 *
 * THE CACHING RULES, AND WHY EACH IS WHAT IT IS
 * --------------------------------------------
 *   BUILD ASSETS (/_next/static/*)   cache first, forever.
 *     Content-hashed by Next, so a URL's content can never change. Going to the
 *     network to re-confirm that is pure latency.
 *
 *   RECORD DETAIL (/r/*.json)        stale while revalidate.
 *     Immutable per deploy but not content-hashed. Serving the cached copy
 *     instantly and refreshing behind it is right for a pilgrim comparing three
 *     temples: the second look is free, and a correction still lands next time.
 *
 *   PAGES (navigations)              network first, fall back to cache.
 *     A record page carries citations and a completeness badge, and both are
 *     claims about what we have sourced TODAY. Serving a stale one when the
 *     network is available would publish yesterday's claim; the cache is the
 *     safety net, not the default.
 *
 *   THE API (/api/*)                 never cached, never intercepted.
 *     /api/chat and the voice routes cost money per call and are not
 *     idempotent. A replayed answer is also a citation shown against a question
 *     it was not generated for, which is the one thing this project must not do.
 *
 * WHAT IS DELIBERATELY NOT PRECACHED
 * ----------------------------------
 * All 3,031 record files (1.75 MB) could be pulled down on install. They are
 * not, because that spends a stranger's mobile data on 3,030 temples they did
 * not ask about. Records are cached as they are read.
 */

// Bumped by scripts/build-map-artefacts.mjs on every build, so a deploy cannot
// serve a half-old shell against a new build's hashed assets.
const VERSION = "496168aac197";
const SHELL = `tirtha-shell-${VERSION}`;
const RUNTIME = `tirtha-runtime-${VERSION}`;

/** The least that must be there for the atlas to open with no network at all. */
const SHELL_URLS = ["/", "/sites", "/offline", "/manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL).then((cache) =>
      // addAll is atomic: one 404 would leave NO shell cached. Each is added
      // individually so a single missing route cannot defeat the whole install.
      Promise.all(SHELL_URLS.map((url) =>
        cache.add(new Request(url, { cache: "reload" })).catch(() => {}))),
    ).then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        // Every cache from a previous VERSION goes. Without this each deploy
        // leaves its predecessor's assets on the device for ever.
        keys.filter((k) => k.startsWith("tirtha-") && k !== SHELL && k !== RUNTIME)
            .map((k) => caches.delete(k)),
      ))
      .then(() => self.clients.claim()),
  );
});

const cacheFirst = async (request, cacheName) => {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
};

const staleWhileRevalidate = async (request, cacheName) => {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  const fresh = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => null);
  // The cached copy wins the race when there is one; otherwise wait for the
  // network. `fresh` keeps running either way, so the next read is current.
  return hit ?? (await fresh) ?? Response.error();
};

const networkFirst = async (request, cacheName) => {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    // caches.match() searches EVERY cache, not just this one. That matters: the
    // shell routes ("/", "/sites") are precached into SHELL at install, while
    // pages visited later land in RUNTIME. Looking only in RUNTIME meant the
    // homepage — the one page guaranteed to be cached — fell through to the
    // offline page the moment the network went away, which is the exact
    // opposite of what precaching it was for. Caught by pulling the plug on a
    // real server; it cannot be caught by reading the code.
    const hit = (await cache.match(request)) ?? (await caches.match(request));
    if (hit) return hit;
    // Nothing cached and nothing reachable. A branded page that says so beats
    // the browser's dinosaur, because it can still offer the map, which IS
    // cached — the reader is not actually stuck.
    return (await caches.match("/offline")) ?? Response.error();
  }
};

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  // Same-origin only. A cross-origin request here is Google Fonts or an
  // outbound citation link, and caching either is not this worker's business.
  if (url.origin !== self.location.origin) return;

  // The API is never intercepted: it spends money, it is not idempotent, and a
  // replayed answer would carry citations generated for a different question.
  if (url.pathname.startsWith("/api/")) return;

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, SHELL));
    return;
  }

  if (url.pathname.startsWith("/r/") && url.pathname.endsWith(".json")) {
    event.respondWith(staleWhileRevalidate(request, RUNTIME));
    return;
  }

  /*
   * Next's RSC prefetches.
   *
   * <Link> prefetches every route in the nav drawer as `/sites?_rsc=…` with
   * mode "cors", not "navigate", so the branch below never saw them. Offline
   * they failed with ERR_CONNECTION_REFUSED — twelve console errors on the
   * homepage, one pair per drawer link. Next degrades to a full navigation, so
   * nothing broke, but a route the reader had already prefetched was
   * unavailable precisely when the prefetch would have paid off.
   *
   * Cached under a key WITHOUT the _rsc token: it is a cache-busting build
   * hash, so keying on it means every deploy strands the previous build's
   * prefetches in the cache, matched by nothing and evicted by nothing.
   */
  if (url.searchParams.has("_rsc")) {
    const key = new Request(url.origin + url.pathname + "__rsc", { headers: request.headers });
    event.respondWith(
      caches.open(RUNTIME).then(async (cache) => {
        const hit = await cache.match(key);
        const fresh = fetch(request)
          .then((response) => {
            if (response.ok) cache.put(key, response.clone());
            return response;
          })
          .catch(() => null);
        return hit ?? (await fresh) ?? new Response("", { status: 504 });
      }),
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, RUNTIME));
    return;
  }

  // Icons, the manifest, and anything else static and same-origin.
  if (/\.(?:svg|png|ico|webmanifest|woff2?)$/.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request, SHELL));
  }
});

/**
 * "Save this for offline" from the page.
 *
 * An explicit action, never automatic: pulling 1.75 MB of records onto someone's
 * phone without asking is spending their data on a decision they did not make.
 */
self.addEventListener("message", (event) => {
  const data = event.data;
  if (!data || data.type !== "cache-records" || !Array.isArray(data.ids)) return;
  event.waitUntil(
    caches.open(RUNTIME).then((cache) =>
      Promise.all(data.ids.slice(0, 500).map((id) =>
        cache.add(`/r/${encodeURIComponent(id)}.json`).catch(() => {}))),
    ),
  );
});
